// Create address (name) (value) (address) (run without screen refresh)
void Glue3DSprite::CreateAddress(Value name, Value value, Value address)
{
    stage.ramEngineData.Replace((address.Num() - 1) * 2 + 1, name);
    stage.ramEngineData.Replace((address.Num() - 1) * 2 + 2, value);
}

// Gui element (element name) , element data; (run without screen refresh)
void Glue3DSprite::GuiElementElementData(Value elementName)
{
    if (Eq(stage.allExportState, 0))
    {
        if (Eq(elementName, u"scrollbar"_s))
        {
            ScrollerElement();
        }
        else if (Eq(elementName, u"margin"_s))
        {
            if (Eq(stage.guiFreeze, 0))
            {
                MarginElement();
            }
        }
        else if (Eq(elementName, u"dropdown"_s))
        {
            DropdownElement();
        }
        else if (Eq(elementName, u"menu"_s))
        {
            MenuElement();
        }
    }
}

// Render2D (name) on (x) (y) dir (dir) size (size) gbc (g) (b) (c) interactive (i) (except1) (except2) shadow (shadow) hover message (hover message) (run without screen refresh)
void Glue3DSprite::Render2DOnDirSizeGbcInteractiveShadowHoverMessage(Value name, Value x, Value y, Value dir, Value size, Value g, Value b, Value c, Value i, Value except1, Value except2, Value shadow, Value hoverMessage)
{
    stage.guiHover = 0;
    SetEffect(Effect::Color, c.Num());
    SwitchCostume(name);
    PointInDirection(dir.Num());
    GoTo(x.Num() + (stage.guiWindowEffect.Num() * -150), y.Num());
    SetSize(size.Num());
    if (Eq(shadow, 1))
    {
        SetEffect(Effect::Brightness, -100);
        SetEffect(Effect::Ghost, 50 + g.Num());
        SetSize(size.Num() * 1.1);
        Stamp();
        stage.guiTemp1 = 500 / Nz(std::sqrt((XPosition() - MouseX()) * (XPosition() - MouseX()) + ((YPosition() - MouseY()) * (YPosition() - MouseY()))));
        SetEffect(Effect::Brightness, b.Num() + (drawingDragged_ ? 0.0 : (stage.guiTemp1.Num() * Num(Lt(stage.guiTemp1, 35)) + (35 * Num(Gt(stage.guiTemp1, 35)))))); // EDITED: no glow on a dragged item
    }
    else if (Eq(shadow, 2))
    {
        SetEffect(Effect::Brightness, -100);
        SetEffect(Effect::Ghost, 50 + g.Num());
        SetSize(size.Num() * 1);
        ChangeY(Nz(size.Num() / 100) * -10);
        Stamp();
        ChangeY(Nz(size.Num() / 100) * 10);
        stage.guiTemp1 = 500 / Nz(std::sqrt((XPosition() - MouseX()) * (XPosition() - MouseX()) + ((YPosition() - MouseY()) * (YPosition() - MouseY()))));
        SetEffect(Effect::Brightness, b.Num() + (drawingDragged_ ? 0.0 : (stage.guiTemp1.Num() * Num(Lt(stage.guiTemp1, 35)) + (35 * Num(Gt(stage.guiTemp1, 35)))))); // EDITED: no glow on a dragged item
    }
    else
    {
        SetEffect(Effect::Brightness, b.Num());
    }
    SetEffect(Effect::Ghost, g.Num());
    SetSize(size.Num());
    stage.guiClick = 0;
    if (Eq(i, 1) && TouchingMouse())
    {
        SetSize(size.Num() * 1.03);
        ChangeEffect(Effect::Brightness, 10);
        if (Eq(stage.guiFreeze, 0))
        {
            stage.guiPointerID = u"click"_s;
            stage.guiHover = 1;
            if (Gt(hoverMessage, u""_s))
            {
                stage.guiInfo = 1;
                stage.guiInfoName = hoverMessage;
                stage.guiInfoX = stage.guiInfoX.Num() + Nz((stage.guiPointerX.Num() * 0.92 - stage.guiInfoX.Num()) / 3);
                stage.guiInfoY = stage.guiInfoY.Num() + Nz((y.Num() - 30 - stage.guiInfoY.Num()) / 2);
            }
            if (MouseDown() && Eq(stage.guiPrevMouseState, 0))
            {
                if (Eq(stage.ramEngineData.Item(26), 0) || Eq(except1, 1))
                {
                    StartSound(u"Windows Vista Beta Balloon"_s);
                    SetSize(size.Num() * 0.98);
                    stage.guiClick = 1;
                }
            }
        }
    }
    if ((Eq(except2, u""_s) && (!(Eq(name, u"_gui.dark"_s) || Eq(name, u"_gui.darkfade"_s)))) && Eq(stage.ramEngineData.Item(78), u"dark"_s))
    {
        ChangeEffect(Effect::Brightness, -100);
        Stamp();
        SetSize(SizeReporter() * 0.9);
        ChangeEffect(Effect::Color, -5);
        ChangeEffect(Effect::Brightness, 90);
        Stamp();
    }
    else
    {
        ChangeEffect(Effect::Ghost, stage.guiWindowEffect.Num() * -3000);
        Stamp();
    }
}

