// decode ID (ID) (max) seperator (seperator) include seperator (includeseperator) specialdot (specialdot) (run without screen refresh)
void Glue3DSprite::DecodeIDSeperatorIncludeSeperatorSpecialdot(Value iD, Value max_, Value seperator, Value includeseperator, Value specialdot)
{
    stage.decodedElements.DeleteAll();
    stage.proccessDecode = u""_s;
    stage.proccessDecodeIndex = 1;
    if (Eq(seperator, u""_s))
    {
        for (double i1 = 0, times1 = Round(iD.Str().Length()); i1 < times1; i1++)
        {
            stage.proccessDecode = stage.proccessDecode.Str() + LetterOf(stage.proccessDecodeIndex.Num(), iD.Str());
            if (Eq(LetterOf(stage.proccessDecodeIndex.Num() + 1, iD.Str()), u","_s))
            {
                stage.decodedElements.Add(stage.proccessDecode);
                stage.proccessDecode = u""_s;
                stage.proccessDecodeIndex = stage.proccessDecodeIndex.Num() + 1;
            }
            stage.proccessDecodeIndex = stage.proccessDecodeIndex.Num() + 1;
            if (Gt(max_, u""_s) && Gt(stage.decodedElements.Length(), max_))
            {
                return;
            }
        }
    }
    else if (Eq(includeseperator, 1))
    {
        if (Eq(specialdot, u""_s))
        {
            for (double i1 = 0, times1 = Round(iD.Str().Length()); i1 < times1; i1++)
            {
                stage.proccessDecode = stage.proccessDecode.Str() + LetterOf(stage.proccessDecodeIndex.Num(), iD.Str());
                if (Contains(seperator.Str(), LetterOf(stage.proccessDecodeIndex.Num(), iD.Str())))
                {
                    stage.decodedElements.Add(stage.proccessDecode);
                    stage.proccessDecode = u""_s;
                }
                stage.proccessDecodeIndex = stage.proccessDecodeIndex.Num() + 1;
            }
        }
        else
        {
            stage.proccessTemp1 = 0;
            for (double i1 = 0, times1 = Round(iD.Str().Length()); i1 < times1; i1++)
            {
                stage.proccessDecode = stage.proccessDecode.Str() + LetterOf(stage.proccessDecodeIndex.Num(), iD.Str());
                if ((Eq(stage.proccessTemp1, 0) && Eq(specialdot, LetterOf(stage.proccessDecodeIndex.Num(), iD.Str()))) || Contains(seperator.Str(), LetterOf(stage.proccessDecodeIndex.Num(), iD.Str())))
                {
                    stage.decodedElements.Add(stage.proccessDecode);
                    stage.proccessDecode = u""_s;
                    stage.proccessTemp1 = 1;
                }
                stage.proccessDecodeIndex = stage.proccessDecodeIndex.Num() + 1;
            }
        }
    }
    else if (Eq(specialdot, u""_s))
    {
        for (double i1 = 0, times1 = Round(iD.Str().Length()); i1 < times1; i1++)
        {
            if (!Contains(seperator.Str(), LetterOf(stage.proccessDecodeIndex.Num(), iD.Str())))
            {
                stage.proccessDecode = stage.proccessDecode.Str() + LetterOf(stage.proccessDecodeIndex.Num(), iD.Str());
            }
            if (Contains(seperator.Str(), LetterOf(stage.proccessDecodeIndex.Num(), iD.Str())))
            {
                stage.decodedElements.Add(stage.proccessDecode);
                stage.proccessDecode = u""_s;
            }
            stage.proccessDecodeIndex = stage.proccessDecodeIndex.Num() + 1;
        }
    }
    else
    {
        stage.proccessTemp1 = 0;
        for (double i1 = 0, times1 = Round(iD.Str().Length()); i1 < times1; i1++)
        {
            if (!((Eq(stage.proccessTemp1, 0) && Eq(specialdot, LetterOf(stage.proccessDecodeIndex.Num(), iD.Str()))) || Contains(seperator.Str(), LetterOf(stage.proccessDecodeIndex.Num(), iD.Str()))))
            {
                stage.proccessDecode = stage.proccessDecode.Str() + LetterOf(stage.proccessDecodeIndex.Num(), iD.Str());
            }
            if ((Eq(stage.proccessTemp1, 0) && Eq(specialdot, LetterOf(stage.proccessDecodeIndex.Num(), iD.Str()))) || Contains(seperator.Str(), LetterOf(stage.proccessDecodeIndex.Num(), iD.Str())))
            {
                stage.decodedElements.Add(stage.proccessDecode);
                stage.proccessDecode = u""_s;
                stage.proccessTemp1 = 1;
            }
            stage.proccessDecodeIndex = stage.proccessDecodeIndex.Num() + 1;
        }
    }
}

