// Main.Time (run without screen refresh)
void Glue3DSprite::MainTime()
{
    stage.timeDelta = Timer() - stage.timeTimer.Num();
    stage.timeTimer = Timer();
    stage.timeFps = std::floor(Nz(1 / stage.timeDelta.Num()));
    stage.timeDelta = stage.timeDelta.Num() * TimeScale(); // EDITED: time.scale
    stage.timeClockMode = stage.ramEngineData.Item(214);
    if (Gt(stage.timeFps, stage.highestFps))
    {
        stage.highestFps = stage.timeFps;
    }
}

// Create Folder (name) (run without screen refresh)
void Glue3DSprite::CreateFolder(Value name)
{
    stage.engineFiles.Add(name);
    stage.engineFiles.Add(0);
    stage.engineFiles.Add(name.Str() + u".end"_s);
    stage.fileFiles = stage.fileFiles.Num() + 1;
}

// message (Message) (Icon) (Sound) (Dismissable) (run without screen refresh)
void Glue3DSprite::Message(Value message, Value icon, Value sound, Value dismissable)
{
    stage.errorDismissable = dismissable;
    stage.errorMessage = message;
    stage.errorIcon = icon;
    stage.errorPopup = 1;
    stage.errorEffect = 1;
    stage.guiFreeze = 1 - dismissable.Num();
    StartSound(sound);
}

// Element: Error (run without screen refresh)
void Glue3DSprite::ElementError()
{
    if (Eq(stage.errorDismissable, u""_s))
    {
        stage.guiFreeze = 1 - stage.guiFreeze.Num();
    }
    Render2DOnDirSizeGbcInteractiveShadowHoverMessage(u"_gui.dark"_s, 0, 0, 90, 100, 0, 0, 0, 0, u""_s, u""_s, 0, u""_s);
    RenderBoxToBoxTypeBorderAlternate(-75, 45, 75, -20, 1, 2, Num(Gt(stage.guiFocusEffect, 0)) * 1, u""_s, u""_s);
    Render2DOnDirSizeGbcInteractiveShadowHoverMessage(stage.errorIcon, -50, 7 + (Nz(Sin(1000 * stage.timeTimer.Num())) * (stage.errorEffect.Num() * 2)), 90, 65, 10, 0, 0, 1, u""_s, u""_s, 1, stage.errorIcon);
    TextOnScaleCenterGbcCursorLimitScroll(stage.errorMessage, -29, 8 + (Nz(Sin(1000 * stage.timeTimer.Num())) * (stage.errorEffect.Num() * 2)), 0.5 + (Num(Gt(stage.errorMessage.Str().Length(), 15)) * ((stage.errorMessage.Str().Length() - 5) * -0.006)), u""_s, u""_s, 50, -100, 0, u""_s, u""_s, u""_s, u""_s);
    TextOnScaleCenterGbcCursorLimitScroll(u"main"_s, -69, 36, 0.55, u""_s, u""_s, 75, -100, 0, u""_s, u""_s, u""_s, u""_s);
    if (Eq(stage.errorDismissable, u""_s))
    {
        Render2DOnDirSizeGbcInteractiveShadowHoverMessage(u"_button.delete"_s, 63, 35, 90, 38, 30, 0, 0, 1, u""_s, u""_s, 1, u""_s);
        stage.guiFreeze = 1 - stage.guiFreeze.Num();
        if (Eq(stage.guiClick, 1))
        {
            stage.errorPopup = -1;
            stage.guiFreeze = 0;
            if (Eq(stage.errorMessage, u"please import"_s))
            {
                HideList(stage.loadedTextures);
                PlaceholderNamesForExsistingTextures(u"texture"_s);
            }
        }
    }
    else if (MouseDown() && Lt(stage.guiClickLimit, 0))
    {
        stage.errorPopup = -1;
    }
    stage.errorEffect = stage.errorEffect.Num() * 0.9;
}

